//! Versioned golden pixels generated by independent agent-only decoders.
use atelier_image::{DecodeLimits, decode_bmp, decode_gif, decode_png};
use std::path::Path;

#[test]
fn independent_reference_pixels_and_invalid_pngsuite() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/image-reference");
    let mut valid = 0;
    let mut invalid = 0;
    for line in include_str!("../../../tests/image-reference/cases.tsv").lines() {
        let fields: Vec<_> = line.split('\t').collect();
        let bytes = std::fs::read(root.join(fields[1])).unwrap();
        let decoder = match fields[0] {
            "png" => decode_png,
            "gif" => decode_gif,
            "bmp" => decode_bmp,
            _ => panic!("unknown case"),
        };
        let decoded = decoder(&bytes, DecodeLimits::default());
        if fields[4] == "-" {
            assert!(decoded.is_err(), "{} accepted invalid PNG", fields[1]);
            invalid += 1;
        } else {
            let decoded = decoded.unwrap_or_else(|error| panic!("{}: {error}", fields[1]));
            assert_eq!(decoded.width.to_string(), fields[2], "{} width", fields[1]);
            assert_eq!(
                decoded.height.to_string(),
                fields[3],
                "{} height",
                fields[1]
            );
            let expected = std::fs::read(root.join(fields[4])).unwrap();
            assert_eq!(decoded.pixels, expected, "{} RGBA", fields[1]);
            valid += 1;
        }
    }
    assert_eq!(valid, 187);
    assert_eq!(invalid, 14);
}
